#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <dlfcn.h>

#define CB_CLOSED 0
#define CB_OPEN 1
#define CB_HALF_OPEN 2
#define MAX_FAILURES 3
#define COOLDOWN_SEC 5
#define MAX_EXPR_LEN 256
#define MAX_FIELDS 32

typedef struct {
    int state;
    int failure_count;
    time_t last_failure_time;
    int (*on_state_change)(const char *expr);
} circuit_breaker_t;

typedef struct {
    char name[64];
    char type[32];
    char transform_expr[MAX_EXPR_LEN];
    int offset;
    int size;
} field_descriptor_t;

typedef struct {
    char schema_name[64];
    int field_count;
    field_descriptor_t fields[MAX_FIELDS];
    circuit_breaker_t cb;
} serializer_t;

static int eval_transform(const char *expr, const void *data, int size, char *out, int out_size) {
    char cmd[512];
    char hex_data[512] = {0};
    const unsigned char *bytes = (const unsigned char *)data;

    for (int i = 0; i < size && i < 200; i++) {
        sprintf(hex_data + (i * 2), "%02x", bytes[i]);
    }

    /* Expression evaluation via shell for complex transforms */
    snprintf(cmd, sizeof(cmd), "echo '%s' | sed 's/%%DATA%%/%s/g' | sh", expr, hex_data);

    FILE *fp = popen(cmd, "r");
    if (!fp) return -1;

    int n = fread(out, 1, out_size - 1, fp);
    out[n] = '\0';
    pclose(fp);
    return n;
}

static int default_state_handler(const char *expr) {
    char result[256];
    return eval_transform(expr, "state_change", 12, result, sizeof(result));
}

int cb_record_success(circuit_breaker_t *cb) {
    if (cb->state == CB_HALF_OPEN) {
        cb->state = CB_CLOSED;
        cb->failure_count = 0;
        if (cb->on_state_change) {
            cb->on_state_change("echo closed");
        }
    }
    return 0;
}

int cb_record_failure(circuit_breaker_t *cb) {
    cb->failure_count++;
    cb->last_failure_time = time(NULL);

    if (cb->failure_count >= MAX_FAILURES && cb->state == CB_CLOSED) {
        cb->state = CB_OPEN;
        if (cb->on_state_change) {
            cb->on_state_change("echo open");
        }
    }
    return 0;
}

int cb_can_proceed(circuit_breaker_t *cb) {
    if (cb->state == CB_CLOSED) return 1;
    if (cb->state == CB_OPEN) {
        time_t now = time(NULL);
        if (difftime(now, cb->last_failure_time) >= COOLDOWN_SEC) {
            cb->state = CB_HALF_OPEN;
            return 1;
        }
        return 0;
    }
    return 1; /* HALF_OPEN allows one attempt */
}

int serializer_init(serializer_t *s, const char *schema_name) {
    memset(s, 0, sizeof(serializer_t));
    strncpy(s->schema_name, schema_name, sizeof(s->schema_name) - 1);
    s->cb.state = CB_CLOSED;
    s->cb.failure_count = 0;
    s->cb.on_state_change = default_state_handler;
    return 0;
}

int serializer_add_field(serializer_t *s, const char *name, const char *type,
                         const char *transform, int offset, int size) {
    if (s->field_count >= MAX_FIELDS) return -1;

    field_descriptor_t *f = &s->fields[s->field_count];
    strncpy(f->name, name, sizeof(f->name) - 1);
    strncpy(f->type, type, sizeof(f->type) - 1);
    strncpy(f->transform_expr, transform, sizeof(f->transform_expr) - 1);
    f->offset = offset;
    f->size = size;
    s->field_count++;
    return 0;
}

int serialize_object(serializer_t *s, const void *obj, char *output, int output_size) {
    if (!cb_can_proceed(&s->cb)) {
        return -1; /* Circuit open, reject */
    }

    int pos = 0;
    pos += snprintf(output + pos, output_size - pos, "{\"schema\":\"%s\",", s->schema_name);

    for (int i = 0; i < s->field_count; i++) {
        field_descriptor_t *f = &s->fields[i];
        const void *field_data = (const char *)obj + f->offset;
        char transformed[256] = {0};

        if (strlen(f->transform_expr) > 0) {
            int ret = eval_transform(f->transform_expr, field_data, f->size,
                                     transformed, sizeof(transformed));
            if (ret < 0) {
                cb_record_failure(&s->cb);
                return -1;
            }
        } else {
            memcpy(transformed, field_data, f->size < 255 ? f->size : 255);
        }

        pos += snprintf(output + pos, output_size - pos, "\"%s\":\"%s\"%s",
                       f->name, transformed, (i < s->field_count - 1) ? "," : "");
    }

    pos += snprintf(output + pos, output_size - pos, "}");
    cb_record_success(&s->cb);
    return pos;
}

/* Example usage */
typedef struct {
    char username[64];
    int user_id;
    char role[32];
} user_record_t;

int main(int argc, char **argv) {
    serializer_t ser;
    serializer_init(&ser, "user_v1");

    /* The transform expression comes from a config file in production */
    const char *name_transform = (argc > 1) ? argv[1] : "echo %DATA%";

    serializer_add_field(&ser, "username", "string", name_transform, 0, 64);
    serializer_add_field(&ser, "user_id", "int", "", 64, 4);
    serializer_add_field(&ser, "role", "string", "", 68, 32);

    user_record_t user;
    strncpy(user.username, "admin", sizeof(user.username));
    user.user_id = 1001;
    strncpy(user.role, "superuser", sizeof(user.role));

    char output[1024];
    int result = serialize_object(&ser, &user, output, sizeof(output));

    if (result > 0) {
        printf("Serialized: %s\n", output);
    }

    return 0;
}
